import { Link } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { ArrowRight, Minus, Plus, ShieldCheck, ShoppingBag, Trash2, Truck, X } from "lucide-react";
import { FREE_DELIVERY_FROM, cartDetails, useShop } from "../lib/store";
import { formatUZS, getProduct, products } from "../data/mock";
import { EmptyState, ProductCard, cn } from "../lib/ui";
export const CartPage = () => {
  const { t } = useTranslation();
  const { cart, setQty, removeFromCart, clearCart, promo } = useShop();
  const { subtotal, discount, delivery, total } = cartDetails(cart, promo);
  const remaining = Math.max(0, FREE_DELIVERY_FROM - subtotal);
  const progress = Math.min(100, subtotal / FREE_DELIVERY_FROM * 100);
  const recommended = products.filter((p) => !cart.some((c) => c.productId === p.id)).slice(0, 4);
  if (cart.length === 0) {
    return <div className="container-page py-10 sm:py-16">
        <EmptyState
      icon={<ShoppingBag size={30} />}
      title={t("emptyCartTitle")}
      description={t("emptyCartDesc")}
      action={<Link to="/catalog" className="btn-primary btn-sm">{t("emptyCartBtn")} <ArrowRight size={14} /></Link>}
    />
        <div className="mt-10">
          <h2 className="mb-4 section-title">{t("recommended")}</h2>
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
            {recommended.map((p) => <ProductCard key={p.id} product={p} compact />)}
          </div>
        </div>
      </div>;
  }
  return <div className="container-page py-5 sm:py-7">
      <div className="mb-5 flex flex-wrap items-end justify-between gap-2">
        <div>
          <h1 className="font-display text-2xl font-extrabold sm:text-3xl">{t("cartTitle")}</h1>
          <p className="mt-1 text-xs text-[var(--muted)]">{t("cartSubtitle")} · {cart.length} {t("itemsCount")}</p>
        </div>
        <button onClick={clearCart} className="flex items-center gap-1 text-[11px] font-extrabold text-rose-500 transition hover:text-rose-600"><Trash2 size={13} /> {t("clearCart")}</button>
      </div>

      <div className="grid gap-5 lg:grid-cols-[1fr_360px]">
        <div className="space-y-3">
          {cart.map((item) => {
    const product = getProduct(item.productId);
    if (!product) return null;
    return <div key={item.productId} className="card flex gap-3 p-3 sm:gap-4 sm:p-4">
                <Link to={`/product/${product.id}`} className={cn("flex h-20 w-20 shrink-0 items-center justify-center overflow-hidden rounded-2xl bg-gradient-to-br sm:h-24 sm:w-24", product.gradient)}>
                  {product.img ? <img alt={product.name} className="h-full w-full object-contain p-1.5" src={product.img} /> : <span className="text-4xl sm:text-5xl">{product.emoji}</span>}
                </Link>
                <div className="flex min-w-0 flex-1 flex-col">
                  <div className="flex items-start justify-between gap-2">
                    <div className="min-w-0">
                      <p className="text-[10px] font-bold uppercase tracking-wide text-[var(--muted)]">{product.unit}</p>
                      <Link to={`/product/${product.id}`} className="line-clamp-2 text-sm font-extrabold transition hover:text-brand-600">{product.name}</Link>
                    </div>
                    <button onClick={() => removeFromCart(item.productId)} className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-[var(--muted)] transition hover:bg-rose-500/10 hover:text-rose-500"><X size={14} /></button>
                  </div>
                  <div className="mt-auto flex flex-wrap items-end justify-between gap-2 pt-2">
                    <div className="flex items-center gap-1 rounded-xl border bg-[var(--surface)] p-0.5">
                      <button onClick={() => setQty(item.productId, item.qty - 1)} className="flex h-7 w-7 items-center justify-center rounded-lg text-[var(--muted)] transition hover:bg-[var(--surface-2)]"><Minus size={13} /></button>
                      <span className="w-6 text-center text-xs font-extrabold">{item.qty}</span>
                      <button onClick={() => setQty(item.productId, item.qty + 1)} className="flex h-7 w-7 items-center justify-center rounded-lg text-[var(--muted)] transition hover:bg-[var(--surface-2)]"><Plus size={13} /></button>
                    </div>
                    <div className="text-right">
                      <p className="text-[10px] font-bold text-[var(--muted)]">{formatUZS(product.price)} × {item.qty}</p>
                      <p className="font-display text-sm font-extrabold text-brand-700 dark:text-brand-400">{formatUZS(product.price * item.qty)}</p>
                    </div>
                  </div>
                </div>
              </div>;
  })}

          <Link to="/catalog" className="btn-secondary w-full"><Plus size={15} /> {t("addMore")}</Link>

        </div>

        <div className="h-fit space-y-3 lg:sticky lg:top-32">
          <div className="card p-4 sm:p-5">
            <h2 className="font-display text-lg font-extrabold">{t("orderSummary")}</h2>
            <div className="mt-4 space-y-2.5 text-xs">
              <div className="flex justify-between"><span className="text-[var(--muted)]">{t("subtotal")} ({cart.length})</span><b>{formatUZS(subtotal)}</b></div>
              {discount > 0 && <div className="flex justify-between text-brand-600 dark:text-brand-400"><span>{t("discount")}</span><b>−{formatUZS(discount)}</b></div>}
              <div className="flex justify-between"><span className="text-[var(--muted)]">{t("deliveryFee")}</span><b className={delivery === 0 ? "text-brand-600 dark:text-brand-400" : ""}>{delivery === 0 ? t("freeDelivery") : formatUZS(delivery)}</b></div>
              <div className="border-t pt-2.5" />
              <div className="flex items-end justify-between">
                <span className="font-extrabold">{t("total")}</span>
                <span className="font-display text-xl font-extrabold text-brand-700 dark:text-brand-400">{formatUZS(total)}</span>
              </div>
            </div>

            <div className="mt-4 rounded-xl bg-[var(--surface-2)] p-3">
              <div className="flex items-center gap-1.5 text-[10px] font-extrabold">
                <Truck size={13} className="text-brand-500" />
                {remaining > 0 ? `${t("deliveryFreeNote")} ${formatUZS(remaining)}` : `\u{1F389} ${t("freeDelivery")}!`}
              </div>
              <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-[var(--surface-3)]">
                <div className="h-full rounded-full bg-gradient-to-r from-brand-500 to-lime-400 transition-all" style={{ width: `${progress}%` }} />
              </div>
            </div>

            <Link to="/checkout" className="btn-primary mt-4 w-full">{t("proceedCheckout")} <ArrowRight size={16} /></Link>
            <Link to="/catalog" className="btn-ghost mt-1.5 w-full text-xs">{t("continueShopping")}</Link>
            <div className="mt-3 flex items-center justify-center gap-1 text-[10px] font-bold text-[var(--muted)]"><ShieldCheck size={12} /> {t("securePayment")}</div>
          </div>
        </div>
      </div>
    </div>;
};
